// Query pipeline. Streams the source with for...of and stops the instant the answer is settled -- never spreads
// or materialises it into an array first.

export function firstBigNorthern(source) {
	for (const record of source) {
		if (record.region === "north" && record.amountMinor > 5000) {
			return record.id;
		}
	}
	return null;
}

export function topTenDoubled(source) {
	const doubled = [];
	for (const record of source) {
		if (record.amountMinor > 4000) {
			doubled.push(`${record.id}:${record.amountMinor * 2}`);
			if (doubled.length === 10) {
				break;
			}
		}
	}
	return doubled;
}

export function anyOver(source, threshold) {
	for (const record of source) {
		if (record.amountMinor > threshold) {
			return true;
		}
	}
	return false;
}
